#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long k;
    cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    sort(a.begin(), a.end());
    long long lo = 0, hi = a[n - 1] - a[0];
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2, count = 0;
        int l = 0;
        for (int rr = 0; rr < n; rr++) {
            while (a[rr] - a[l] > mid) l++;
            count += rr - l;
        }
        if (count >= k) hi = mid;
        else lo = mid + 1;
    }
    cout << lo << "\n";

    return 0;
}

